import (
	"crypto/ed25519"
	"crypto/rand"
	"crypto/x509"
	"encoding/pem"
	"errors"
	"fmt"
	"os"
)

// ExportPrivateKeyToPEM сохраняет приватный ключ в формате PKCS#8 PEM
func ExportPrivateKeyToPEM(privKey ed25519.PrivateKey, filePath string) error {
	// 1. Преобразуем в универсальный бинарный ASN.1 PKCS#8 формат
	derBytes, err := x509.MarshalPKCS8PrivateKey(privKey)
	if err != nil {
		return fmt.Errorf("failed to marshal PKCS#8: %w", err)
	}

	// 2. Оборачиваем в текстовый PEM-блок
	pemBlock := &pem.Block{
		Type:  "PRIVATE KEY",
		Bytes: derBytes,
	}

	file, err := os.OpenFile(filePath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer file.Close()

	if err := pem.Encode(file, pemBlock); err != nil {
		return fmt.Errorf("failed to encode pem: %w", err)
	}

	return nil
}

// LoadPrivateKeyFromPEM загружает и парсит PKCS#8 PEM ключ
func LoadPrivateKeyFromPEM(filePath string) (ed25519.PrivateKey, error) {
	pemData, err := os.ReadFile(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to read file: %w", err)
	}

	// Декодируем текстовый PEM в бинарный DER
	block, _ := pem.Decode(pemData)
	if block == nil || block.Type != "PRIVATE KEY" {
		return nil, errors.New("failed to find valid 'PRIVATE KEY' PEM block")
	}

	// Парсим универсальную структуру PKCS#8
	parsedKey, err := x509.ParsePKCS8PrivateKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("failed to parse PKCS#8: %w", err)
	}

	edKey, ok := parsedKey.(ed25519.PrivateKey)
	if !ok {
		return nil, errors.New("key in PEM is not an Ed25519 private key")
	}

	return edKey, nil
}

func main() {
	_, privKey, _ := ed25519.GenerateKey(rand.Reader)
	pemPath := "ed25519_identity.pem"
	defer os.Remove(pemPath)

	if err := ExportPrivateKeyToPEM(privKey, pemPath); err != nil {
		panic(err)
	}
	fmt.Println("Приватный ключ успешно экспортирован в PKCS#8 PEM с правами 0600!")

	rawPEM, _ := os.ReadFile(pemPath)
	fmt.Printf("\nСодержимое файла на диске:\n%s\n", string(rawPEM))

	restoredKey, err := LoadPrivateKeyFromPEM(pemPath)
	if err != nil {
		panic(err)
	}
	fmt.Printf("Ключ успешно загружен и восстановлен! Длина: %d байт\n", len(restoredKey))
}

package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"errors"
	"fmt"
	"io"
)

// KeyStore хранит версионированные мастер-ключи (KEK)
type KeyStore struct {
	keys           map[uint32][]byte
	currentVersion uint32
}

func NewKeyStore() *KeyStore {
	ks := &KeyStore{keys: make(map[uint32][]byte)}
	ks.Rotate() // Инициализируем версию 1
	return ks
}

func (ks *KeyStore) Rotate() uint32 {
	ks.currentVersion++
	newKey := make([]byte, 32)
	_, _ = io.ReadFull(rand.Reader, newKey)
	ks.keys[ks.currentVersion] = newKey
	return ks.currentVersion
}

type Record struct {
	KEKVersion   uint32 // Версия мастер-ключа, которым зашифрован DEK
	EncryptedDEK []byte // Зашифрованный сессионный ключ (48 байт)
	DEKNonce     []byte // Nonce для KEK
	DataNonce    []byte // Nonce для данных
	Ciphertext   []byte // Полезная нагрузка
}

func sealAES(plaintext, key []byte) ([]byte, []byte, error) {
	b, _ := aes.NewCipher(key)
	g, _ := cipher.NewGCM(b)
	nonce := make([]byte, g.NonceSize())
	_, _ = io.ReadFull(rand.Reader, nonce)
	return g.Seal(nil, nonce, plaintext, nil), nonce, nil
}

func openAES(ciphertext, key, nonce []byte) ([]byte, error) {
	b, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	g, err := cipher.NewGCM(b)
	if err != nil {
		return nil, err
	}
	return g.Open(nil, nonce, ciphertext, nil)
}

func EncryptRecord(payload []byte, ks *KeyStore) (*Record, error) {
	// 1. Одноразовый DEK
	dek := make([]byte, 32)
	_, _ = io.ReadFull(rand.Reader, dek)

	// 2. Шифруем полезную нагрузку
	encData, dataNonce, _ := sealAES(payload, dek)

	// 3. Шифруем DEK текущей версией KEK
	curVer := ks.currentVersion
	kek := ks.keys[curVer]
	encDEK, dekNonce, _ := sealAES(dek, kek)

	return &Record{
		KEKVersion:   curVer,
		EncryptedDEK: encDEK,
		DEKNonce:     dekNonce,
		DataNonce:    dataNonce,
		Ciphertext:   encData,
	}, nil
}

// ReencryptRecord меняет версию KEK без расшифрования тела данных!
func ReencryptRecord(rec *Record, ks *KeyStore) error {
	if rec.KEKVersion == ks.currentVersion {
		return nil // Уже на последней версии
	}

	oldKEK, ok := ks.keys[rec.KEKVersion]
	if !ok {
		return errors.New("old KEK version not found")
	}

	// Расшифровываем ТОЛЬКО 32-байтный DEK
	dek, err := openAES(rec.EncryptedDEK, oldKEK, rec.DEKNonce)
	if err != nil {
		return fmt.Errorf("failed decrypting DEK: %w", err)
	}

	// Шифруем DEK новой версией KEK
	newKEK := ks.keys[ks.currentVersion]
	newEncDEK, newDEKNonce, err := sealAES(dek, newKEK)
	if err != nil {
		return err
	}

	// Обновляем метаданные конверта. Полезная нагрузка Ciphertext не тронута!
	rec.KEKVersion = ks.currentVersion
	rec.EncryptedDEK = newEncDEK
	rec.DEKNonce = newDEKNonce
	return nil
}

func DecryptRecord(rec *Record, ks *KeyStore) ([]byte, error) {
	kek, ok := ks.keys[rec.KEKVersion]
	if !ok {
		return nil, errors.New("KEK version not found in store")
	}

	dek, err := openAES(rec.EncryptedDEK, kek, rec.DEKNonce)
	if err != nil {
		return nil, err
	}

	return openAES(rec.Ciphertext, dek, rec.DataNonce)
}

func main() {
	ks := NewKeyStore()
	fmt.Printf("Инициализировано хранилище с активной версией KEK: v%d\n", ks.currentVersion)

	rec, _ := EncryptRecord([]byte("Large Database Payload (100 MB Video File)"), ks)
	fmt.Printf("Запись сохранена: зашифрована KEK v%d\n", rec.KEKVersion)

	// ПЛАНОВАЯ РОТАЦИЯ КЛЮЧЕЙ
	newVer := ks.Rotate()
	fmt.Printf("\nВыполнена плановая ротация! Новая активная версия KEK: v%d\n", newVer)

	// Фоновый воркер перешифровывает запись
	if err := ReencryptRecord(rec, ks); err != nil {
		panic(err)
	}
	fmt.Printf("Запись успешно перешифрована на KEK v%d (тело файла не читалось!)\n", rec.KEKVersion)

	// Проверяем чтение обновленной записи
	plaintext, err := DecryptRecord(rec, ks)
	if err != nil {
		panic(err)
	}
	fmt.Printf("Успешно прочитано: %s\n", string(plaintext))
}

package main

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
)

// MockKMS имитирует защищенный сервис управления ключами
type MockKMS struct {
	masterKEK []byte // Хранится только внутри HSM
}

type DataKeyResponse struct {
	PlaintextKey   []byte // Открытый ключ для локального шифрования
	CiphertextBlob []byte // Ключ, зашифрованный KEK
}

func NewMockKMS() *MockKMS {
	kek := make([]byte, 32)
	_, _ = io.ReadFull(rand.Reader, kek)
	return &MockKMS{masterKEK: kek}
}

// GenerateDataKey моделирует вызов AWS KMS GenerateDataKey
func (kms *MockKMS) GenerateDataKey() (*DataKeyResponse, error) {
	dek := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, dek); err != nil {
		return nil, err
	}

	// Шифруем DEK с помощью мастер-ключа KEK
	block, _ := aes.NewCipher(kms.masterKEK)
	gcm, _ := cipher.NewGCM(block)
	nonce := make([]byte, gcm.NonceSize())
	_, _ = io.ReadFull(rand.Reader, nonce)

	ciphertextBlob := gcm.Seal(nonce, nonce, dek, nil)

	return &DataKeyResponse{
		PlaintextKey:   dek,
		CiphertextBlob: ciphertextBlob,
	}, nil
}

// DecryptKey моделирует вызов AWS KMS Decrypt
func (kms *MockKMS) DecryptKey(ciphertextBlob []byte) ([]byte, error) {
	block, _ := aes.NewCipher(kms.masterKEK)
	gcm, _ := cipher.NewGCM(block)
	nonceSize := gcm.NonceSize()
	if len(ciphertextBlob) < nonceSize {
		return nil, errors.New("invalid ciphertext blob")
	}

	return gcm.Open(nil, ciphertextBlob[:nonceSize], ciphertextBlob[nonceSize:], nil)
}

// EncryptFileEnvelope шифрует файл локально по паттерну KMS
func EncryptFileEnvelope(fileContent []byte, kms *MockKMS) ([]byte, error) {
	// 1. Получаем DEK из KMS
	dataKey, err := kms.GenerateDataKey()
	if err != nil {
		return nil, err
	}
	// Затираем открытый DEK в RAM после использования!
	defer func() {
		for i := range dataKey.PlaintextKey {
			dataKey.PlaintextKey[i] = 0
		}
	}()

	// 2. Локальное шифрование данных через AES-GCM
	block, _ := aes.NewCipher(dataKey.PlaintextKey)
	gcm, _ := cipher.NewGCM(block)
	nonce := make([]byte, gcm.NonceSize())
	_, _ = io.ReadFull(rand.Reader, nonce)
	encryptedFile := gcm.Seal(nil, nonce, fileContent, nil)

	// 3. Формируем конверт: [LenDEK (2B)][CiphertextBlob DEK][Nonce (12B)][EncryptedFile]
	buf := new(bytes.Buffer)
	_ = binary.Write(buf, binary.BigEndian, uint16(len(dataKey.CiphertextBlob)))
	buf.Write(dataKey.CiphertextBlob)
	buf.Write(nonce)
	buf.Write(encryptedFile)

	return buf.Bytes(), nil
}

// DecryptFileEnvelope расшифровывает файл через KMS
func DecryptFileEnvelope(envelope []byte, kms *MockKMS) ([]byte, error) {
	if len(envelope) < 2 {
		return nil, errors.New("envelope too short")
	}

	dekLen := binary.BigEndian.Uint16(envelope[:2])
	offset := 2 + int(dekLen)
	if len(envelope) < offset+12 {
		return nil, errors.New("corrupted envelope structure")
	}

	encryptedDEK := envelope[2:offset]
	nonce := envelope[offset : offset+12]
	encryptedData := envelope[offset+12:]

	// 1. Расшифровываем DEK через KMS
	plainDEK, err := kms.DecryptKey(encryptedDEK)
	if err != nil {
		return nil, fmt.Errorf("KMS decrypt failed: %w", err)
	}
	defer func() {
		for i := range plainDEK {
			plainDEK[i] = 0
		}
	}()

	// 2. Локально расшифровываем файл
	block, _ := aes.NewCipher(plainDEK)
	gcm, _ := cipher.NewGCM(block)
	return gcm.Open(nil, nonce, encryptedData, nil)
}

func main() {
	kms := NewMockKMS()

	payload := []byte("Large Analytical Dump: 50,000 Financial Records for Tax Audit 2026")

	envelope, err := EncryptFileEnvelope(payload, kms)
	if err != nil {
		panic(err)
	}
	fmt.Printf("Конверт создан! Размер: %d байт (оригинал: %d байт)\n", len(envelope), len(payload))

	restored, err := DecryptFileEnvelope(envelope, kms)
	if err != nil {
		panic(err)
	}
	fmt.Printf("Успешно расшифровано: %s\n", string(restored))
}

